/**
 * Hand-edited after generation. Links changed from page | service | path | external to internal | external
 * (src/fields/link.ts). The generated enum changes cast the old values, so every table first maps
 * them: page, service and path become internal (no path links existed); down maps internal back to
 * page or service. Link objects inside JSON sections are converted by a recursive function.
 */
function convertSectionLinks(direction: 'up' | 'down') {
  const replacement =
    direction === 'up'
      ? `CASE WHEN v #>> '{}' IN ('page', 'service', 'path') THEN '"internal"'::jsonb ELSE v END`
      : `CASE WHEN v #>> '{}' = 'internal' THEN to_jsonb(CASE WHEN j->>'page' IS NOT NULL THEN 'page' ELSE 'service' END) ELSE v END`
  return `
  CREATE FUNCTION pg_temp.convert_links(j jsonb) RETURNS jsonb LANGUAGE plpgsql AS $fn$
  BEGIN
    IF jsonb_typeof(j) = 'array' THEN
      RETURN (SELECT coalesce(jsonb_agg(pg_temp.convert_links(v) ORDER BY i), '[]'::jsonb)
        FROM jsonb_array_elements(j) WITH ORDINALITY AS a(v, i));
    ELSIF jsonb_typeof(j) = 'object' THEN
      RETURN (SELECT coalesce(jsonb_object_agg(k,
          CASE WHEN k = 'type' AND j ? 'newTab' THEN ${replacement} ELSE pg_temp.convert_links(v) END), '{}'::jsonb)
        FROM jsonb_each(j) AS e(k, v));
    END IF;
    RETURN j;
  END $fn$;
  DO $do$ DECLARE c record; BEGIN
    FOR c IN SELECT table_name, column_name FROM information_schema.columns
      WHERE table_schema = 'public' AND data_type = 'jsonb' AND column_name IN ('sections', 'version_sections')
    LOOP
      EXECUTE format('UPDATE %I SET %I = pg_temp.convert_links(%I) WHERE %I IS NOT NULL', c.table_name, c.column_name, c.column_name, c.column_name);
    END LOOP;
  END $do$;
  DROP FUNCTION pg_temp.convert_links(jsonb);`
}

